const W = game.everglades.parts.wildlife; const T = game.THREE; let best = null; for (const c of W.cells.values()) for (const g of (s.bird ? c.birds : c.gators)) { if (g.gone || (s.bird ? false : g.inWater !== !!s.wet)) continue; const d = Math.hypot(g.x - s.at[0], g.z - s.at[1]); if (!best || d < best.d) best = { g, d }; } if (!best) return 'none';
 const g = best.g, a = s.az || 0.8, D = s.dist || 7; const eye = new T.Vector3(g.x + Math.cos(a) * D, g.y + (s.eh || 1.6), g.z + Math.sin(a) * D), look = new T.Vector3(g.x, g.y + 0.3, g.z);
 game.cameraOverride = (dt, cam) => { cam.position.copy(eye); cam.lookAt(look); if (cam.fov !== 50) { cam.fov = 50; cam.updateProjectionMatrix(); } return true; }; window.__vegShotCam = [eye.toArray(), look.toArray()]; return { x: g.x, z: g.z, m: g.m };

